fn max(a: &Vec<i32>) -> usize {
    // We assume `a` is non-empty as per the problem statement.
    let mut max_idx: usize = 0;
    let mut max_val: i32 = a[0];

    for i in 1..a.len() {
        if a[i] > max_val {
            max_val = a[i];
            max_idx = i;
        }
    }

    max_idx
}

